Object.assign(actions,{U:'U',"U'":"U'",U2:'U2',leave:''});
const intentOptions={done:'Leave this piece in place',align:'Align this upper edge with a side center',insert:'Insert this upper edge into the middle layer',extract:'Bring this middle edge into the upper layer'};
const routines='A right insertion takes the edge at local UF into FR: its front-facing color matches the front center and its up-facing color matches the right center. Left insertion similarly takes UF into FL with the up-facing color matching the left center. Either routine ejects the previous occupant of that middle slot into the upper layer, and restores the bottom layer. Upper turns reposition upper pieces without moving middle or bottom pieces. A piece is solved only when both stickers match their centers, including orientation.';
