export function request(state:CubeData,target:string,variant:Variant,intention?:string):JevRequest {
 const p=pieces(state).find(p=>p.piece===target)!;
 const faceWords:Record<string,string>={U:'up',D:'down',F:'front',R:'right',B:'back',L:'left'};
