 return {model:'jev-1.13.0',state:{centers:colors,target:{position:p.position,currentLayer:p.position.includes('U')?'upper':'middle',currentLocation:[...p.position].map(f=>faceWords[f]).join(' / '),stickers:p.stickers,visibleStickers:Object.entries(p.stickers).map(([color,f])=>({color,facing:faceWords[f],adjacentCenter:colors[f]}))},goal:'Solve the selected edge with both stickers matching centers. This piece belongs in the middle layer eventually; its current location is given separately. Preserve the completed bottom layer after a complete action. Choose one useful next action, possibly preparation.',frame:'Fixed U up, D down, F front, R right, B back, L left. For routines, @face names the local front; U/D stay fixed. Turns are clockwise as viewed directly at the turned face.',...(intention===undefined?{}:{previousIntention:intention})},questions:{...(intention===undefined?{location:{type:'choice' as const,instructions:'Where is the selected piece NOW? Use current location only, not where it belongs. This question is independent of intention.',criteria:{upper:'Currently in the upper layer',middle:'Currently in the middle layer'}}}:{}),[intention===undefined?'intention':'action']:{type:'choice',instructions:[teaching,variant==='explicit'?rules:'Infer the appropriate next step from the observed relationships and the routine reference.',intention===undefined?'Choose the immediate intention.':'Choose one action carrying out previousIntention. Earlier model answers are not guaranteed correct; no replacement answer is supplied.'].join(' '),criteria:intention===undefined?intentOptions:Object.fromEntries(Object.entries(actions).map(([id,alg])=>[id,id==='leave'?'Leave the cube unchanged':`${id}: ${alg}`]))}}};
